insert into public.site_content_blocks(page_key,block_key,label,default_text) values
('information/patch-165921.html','text-intro','Text · Checked 21 October 2026 new patch. These are companion-site findings, separate from official patch n','Checked 21 October 2026 new patch. These are companion-site findings, separate from official patch notes.'),
('information/patch-165921.html','text-status-title','Text · What has been checked','What has been checked'),
('information/patch-165921.html','note-status-evidence','Text · These are companion-site findings, separate from the official patch notes. Some changes still need c','These are companion-site findings, separate from the official patch notes. Some changes still need confirmation in-game.'),
('information/patch-165921.html','text-status-scope','Text · My Tatari and the stats calculator now support levels 1–3,600. The Horde / Goldrush calculator remai','My Tatari and the stats calculator now support levels 1–3,600. The Horde / Goldrush calculator remains a fixed level-500 comparison.'),
('information/patch-165921.html','text-tatari-title','Text · Bonobean and account levels','Bonobean and account levels'),
('information/patch-165921.html','text-tatari-bonobean','Text · Bonobean, Titanape, Grangutan and Primakong are now integrated across My Tatari, the database, stats','Bonobean, Titanape, Grangutan and Primakong are now integrated across My Tatari, the database, stats calculator, evolution planner, Horde guide/drafter and tierlist tools.'),
('information/patch-165921.html','text-horde-title','Text · Horde Season 3 updates','Horde Season 3 updates'),
('information/patch-165921.html','text-horde-difficulties','Text · The S3 lists Difficulties 1–6. The obtained data show Difficulty 6 has twice Difficulty 4’s enemy AT','The S3 lists Difficulties 1–6. The obtained data show Difficulty 6 has twice Difficulty 4’s enemy ATK and HP; DEF increases by a smaller amount.'),
('information/patch-165921.html','note-horde-seasons','Removed note',''),
('information/patch-165921.html','text-collectibles-title','Text · Collectible additions','Collectible additions'),
('information/patch-165921.html','text-collectibles-accessories','Text · Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lullely, ','Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lullely, Funglet, Taptail, Budboo, Cavyzap, Ringtail and Popa.'),
('information/patch-165921.html','text-collectibles-limits','Removed note',''),
('information/patch-165921.html','text-events-title','Text · Halloween and battle setup','Halloween and battle setup'),
('information/patch-165921.html','text-events-halloween','Text · Halloween Pinball content includes “Trick-or-Treat Time!” and “Halloween Fun!” Event dates are still','Halloween Pinball content includes “Trick-or-Treat Time!” and “Halloween Fun!” Event dates are still unconfirmed.'),
('information/patch-165921.html','text-events-battles','Text · Enemy formations were updated for stages in chapters 24–29, alongside Horde Season 3 wave lineups.','Enemy formations were updated for stages in chapters 24–29, alongside Horde Season 3 wave lineups.'),
('information/patch-165921.html','text-chips-title','Text · Confirmed chip updates','Confirmed chip updates'),
('information/patch-165921.html','text-chips-scope','Text · The 49 chip catalogue entries, qualities, uniqueness and allowed-wave lists are unchanged. Four nume','The 49 chip catalogue entries, qualities, uniqueness and allowed-wave lists are unchanged. Four numeric changes occur in linked Skill records.'),
('information/patch-165921.html','text-chips-shuffle','Text · Shuffle still grants 600 energizers and will shuffle from both the deployed and undeployed Tatari po','Shuffle still grants 600 energizers and will shuffle from both the deployed and undeployed Tatari pool. Contract Employees stay deployed, and their Tatari types are now excluded from the replacement pool. Ordinary replacement units inherit the replaced slots’ grid positions and Horde levels.'),
('information/patch-165921.html','text-skill-balance-title','Text · Tatari Horde skill changes','Tatari Horde skill changes'),
('information/patch-165921.html','text-skill-balance-method','Text · The table below compares the previous and updated skill values, including related buffs and effects.','The table below compares the previous and updated skill values, including related buffs and effects.'),
('information/patch-165921.html','text-mechanics-title','Text · Other Horde mechanics and limits','Other Horde mechanics and limits'),
('information/patch-165921.html','list-mechanics-unchanged-1','Text · All eight deployment/upgrade costs, death refunds, rank stat multipliers and skill unlock indexes ar','All eight deployment/upgrade costs, death refunds, rank stat multipliers and skill unlock indexes are unchanged.'),
('information/patch-165921.html','list-mechanics-unchanged-2','Text · Energy recovery is unchanged: start at 400, initially gain 25 every 5 seconds, decrease the periodic','Energy recovery is unchanged: start at 400, initially gain 25 every 5 seconds, decrease the periodic gain by 5 every 90 seconds, and gain 4 per normal kill or 100 per boss kill.'),
('information/patch-165921.html','list-mechanics-unchanged-3','Text · The rank, season-rank and wave reward tables and the balance table are unchanged.','The rank, season-rank and wave reward tables and the balance table are unchanged.'),
('information/patch-165921.html','list-mechanics-unchanged-4','Text · Horde comparisons remain at level 500. Normal account-level inputs support levels 1–3,600.','Horde comparisons remain at level 500. Normal account-level inputs support levels 1–3,600.'),
('information/patch-165921.html','list-mechanics-unchanged-5','Removed note',''),
('information/patch-165921.html','text-mechanics-tooltips','Text · 86 existing Horde detail entries changed, but many edits only correct labels, formatting, historical','86 existing Horde detail entries changed, but many edits only correct labels, formatting, historical comparison values or buff/nerf arrows. Those display edits must not be counted as additional combat changes.'),
